def validate_image_url(image_url: str) -> None:
    """校验衣服图片 URL 格式，必须是钉钉媒体链接。"""
    if not image_url.startswith("https://down.dingtalk.com/"):
        exit_with_error(
            f"图片链接格式不正确：{image_url!r}\n"
            "衣服图片必须是钉钉媒体链接，格式为：https://down.dingtalk.com/media/xxxx.png",
            code=2,
        )


